import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.Di-jvWLj.js";const u=JSON.parse('{"title":"TypeORM store","description":"","frontmatter":{},"headers":[],"relativePath":"stores/typeorm.md","filePath":"stores/typeorm.md","lastUpdated":1793203625000}'),c={name:"stores/typeorm.md"};function n(d,e,r,i,l,p){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="typeorm-store" tabindex="-1">TypeORM store <a class="header-anchor" href="#typeorm-store" aria-label="Permalink to &quot;TypeORM store&quot;">​</a></h1><p><code>@chamvi/store-typeorm</code> keeps everything the engine persists in Postgres through TypeORM. It passes <code>describeStoreContract</code> unchanged, so the engine behaves the same on memory and on Postgres, also with several replicas on one database.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#E6DFDE;">npm </span><span style="color:#E7C58C;">install</span><span style="color:#E7C58C;"> @chamvi/store-typeorm</span><span style="color:#E7C58C;"> typeorm</span><span style="color:#E7C58C;"> pg</span></span></code></pre></div><p><code>@chamvi/core</code>, <code>typeorm</code> (<code>^1.1.2</code>) and <code>pg</code> (<code>^8</code>) are peer dependencies.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> dataSource = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> DataSource({</span></span>
<span class="line"><span style="color:#E6DFDE;">    type: </span><span style="color:#E7C58C;">&#39;postgres&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    url: process.env.DATABASE_URL,</span></span>
<span class="line"><span style="color:#E6DFDE;">    entities: STORE_ENTITIES,</span></span>
<span class="line"><span style="color:#E6DFDE;">    migrations: STORE_MIGRATIONS,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> dataSource.initialize();</span></span>
<span class="line"><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> migrateStore(dataSource);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> store = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> TypeormStore({ dataSource });</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> engine = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> Engine({</span></span>
<span class="line"><span style="color:#E6DFDE;">    store,</span></span>
<span class="line"><span style="color:#E6DFDE;">    agents: [triage],</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>The store takes an initialized <code>DataSource</code> and never initializes or destroys it. The database must exist; create it beforehand, for example with <code>createDatabase()</code> from <code>typeorm-extension</code>.</p><p>On shutdown, drain the engine before destroying the data source:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">// the store never destroys the data source: the app closes it last</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> shutdown = </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> () </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#E6DFDE;">    clearInterval(purge);</span></span>
<span class="line"><span style="color:#FF7B84;">    await</span><span style="color:#E6DFDE;"> engine.drain();</span></span>
<span class="line"><span style="color:#FF7B84;">    await</span><span style="color:#E6DFDE;"> dataSource.destroy();</span></span>
<span class="line"><span style="color:#E6DFDE;">};</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>dataSource</code></td><td><code>DataSource</code></td><td>required</td><td>An initialized Postgres data source that lists <code>STORE_ENTITIES</code> and <code>STORE_MIGRATIONS</code></td></tr><tr><td><code>clock</code></td><td><code>IClock</code></td><td><code>systemClock</code></td><td>Time source for claims, keys, locks and <code>updatedAt</code></td></tr></tbody></table><h2 id="migrations" tabindex="-1">Migrations <a class="header-anchor" href="#migrations" aria-label="Permalink to &quot;Migrations&quot;">​</a></h2><p><code>migrateStore(dataSource)</code> runs the pending migrations under the Postgres advisory lock <code>chamvi:migrations</code> (<code>MIGRATION_LOCK_NAME</code>). Call it on every boot: replicas that start at once wait for each other, and each migration is applied and recorded once. Each call uses one pooled connection, the one holding the lock, for the migrations as well. chamvi is pre-1.0, so a new version may ship a new migration. The migrations so far: <code>1792195200000-init.ts</code>, <code>1792368000000-artifacts.ts</code>, <code>1792454400000-idempotency-scope.ts</code>, <code>1792540800000-kv-key-collation.ts</code> and <code>1792627200000-agent-revisions.ts</code> (<code>AgentRevisions1792627200000</code>, the table <code>chamvi_agent_revisions</code>).</p><p><code>pendingMigrations(dataSource)</code> resolves the names of the migrations not run yet, in order, without writing anything (it never creates TypeORM&#39;s <code>migrations</code> table); <code>chamvi start --check</code> uses it to refuse a database a start with <code>CHAMVI_MIGRATE=false</code> could not run on (with the default <code>true</code> a start migrates, so the check passes).</p><h2 id="tables" tabindex="-1">Tables <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;Tables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Table</th><th>Holds</th><th>Keys and indexes</th></tr></thead><tbody><tr><td><code>chamvi_runs</code></td><td>Runs; JSON columns for trigger, output, error, usage and wait point; the run&#39;s <code>address</code> in the <code>thread</code> column; claim owner and expiry</td><td>PK <code>id</code> (<code>COLLATE &quot;C&quot;</code>); <code>(agent, status, concurrency_key)</code>; <code>(status, created_at, id)</code></td></tr><tr><td><code>chamvi_steps</code></td><td>Append-only steps</td><td><code>(run_id, step_index)</code></td></tr><tr><td><code>chamvi_checkpoints</code></td><td>The latest checkpoint per run</td><td>PK <code>run_id</code></td></tr><tr><td><code>chamvi_idempotency_keys</code></td><td>Intake keys</td><td>PK <code>(scope, key)</code>; <code>expires_at</code></td></tr><tr><td><code>chamvi_locks</code></td><td>Keyed leases</td><td>PK <code>key</code>; <code>expires_at</code></td></tr><tr><td><code>chamvi_effects</code></td><td>Recorded effect results</td><td>PK <code>key</code></td></tr><tr><td><code>chamvi_kv</code></td><td>Agent key-value state</td><td>PK <code>(agent, key)</code>, <code>key</code> <code>COLLATE &quot;C&quot;</code> (migration <code>1792540800000-kv-key-collation.ts</code>)</td></tr><tr><td><code>chamvi_docs</code></td><td>Agent document collections</td><td>PK <code>(agent, collection, id)</code>; GIN index on <code>doc</code></td></tr><tr><td><code>chamvi_artifacts</code></td><td>Artifact metadata and bytes (<code>data</code> <code>bytea</code>)</td><td>PK <code>id</code>; <code>run_id</code></td></tr><tr><td><code>chamvi_agent_revisions</code></td><td>One revision marker per folder agent: <code>hash</code> varchar(128), <code>changed_at</code></td><td>PK <code>agent</code> varchar(64) <code>COLLATE &quot;C&quot;</code> (migration <code>1792627200000-agent-revisions.ts</code>)</td></tr></tbody></table><h2 id="how-it-keeps-the-contract" tabindex="-1">How it keeps the contract <a class="header-anchor" href="#how-it-keeps-the-contract" aria-label="Permalink to &quot;How it keeps the contract&quot;">​</a></h2><ul><li><strong>Repositories and query builders.</strong> Every method goes through the entities&#39; TypeORM repositories and query builders; the only hand-written fragment is the <code>jsonb_exists</code> key check in <code>docList</code>, which TypeORM has no operator for.</li><li><strong>One statement per atomic operation</strong>, never read-then-write in JavaScript: <ul><li><code>createRun</code>: an insert with <code>orIgnore()</code> (<code>ON CONFLICT DO NOTHING RETURNING id</code>).</li><li><code>claimKey</code> and <code>acquire</code>: an insert with <code>orUpdate()</code> and an overwrite condition (<code>ON CONFLICT DO UPDATE ... WHERE expires_at &lt;= now RETURNING</code>), so an expired key or lock is taken over in the same statement.</li><li><code>claimRun</code> and <code>renewClaim</code>: a conditional update (<code>UPDATE ... WHERE ...</code>) checked by its affected-row count.</li><li>The <code>updateRun</code> guards: a conditional update with <code>RETURNING *</code>; when it matches no row, the store reads the run to throw <code>RunNotFoundError</code> or <code>InvalidRunStateError</code>.</li><li><code>saveCheckpoint</code>: an insert with <code>orUpdate()</code> and the overwrite condition <code>step_index &lt;=</code> the new index.</li><li><code>putArtifact</code>: an insert with <code>orIgnore()</code> returning <code>id</code>.</li><li><code>setAgentRevision</code>: an upsert on <code>agent</code>. The marker needs no atomic compare: the engine reads and writes it under the store lock <code>agents:&lt;name&gt;</code>.</li></ul></li><li><strong>Time from the clock.</strong> The injected <code>IClock</code>&#39;s time is passed as a parameter; queries never call the database&#39;s <code>now()</code>.</li><li><strong>No aliasing.</strong> Values are serialized into the query and parsed out again; nothing is cached in memory.</li><li><strong>Dates.</strong> Timestamps are <code>timestamptz</code>; <code>trigger.receivedAt</code>, <code>trigger.attachments[].createdAt</code>, <code>waiting.expiresAt</code> and <code>waiting.notifiedAt</code> live in JSON and are revived as <code>Date</code>.</li></ul><h2 id="housekeeping" tabindex="-1">Housekeeping <a class="header-anchor" href="#housekeeping" aria-label="Permalink to &quot;Housekeeping&quot;">​</a></h2><p>Expired idempotency keys and locks never block anyone, but they stay in their tables until purged:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">// expired keys and locks stay until purged: purge every hour</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> purge = setInterval(() </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#E6DFDE;">    store.purgeExpired().catch((e: unknown) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> console.error(e));</span></span>
<span class="line"><span style="color:#E6DFDE;">}, </span><span style="color:#E7C58C;">60</span><span style="color:#E6DFDE;"> * </span><span style="color:#E7C58C;">60</span><span style="color:#E6DFDE;"> * </span><span style="color:#E7C58C;">1000</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"><span style="color:#E6DFDE;">purge.unref();</span></span></code></pre></div><p><code>purgeExpired(now?)</code> deletes keys and locks expired at <code>now</code> (default: the clock&#39;s time) and returns <code>{ idempotencyKeys, locks }</code>, the number of rows removed. Effects have no expiry and are never purged. Nothing runs it automatically yet, so schedule it in your app as above.</p><h2 id="differences-from-memorystore" tabindex="-1">Differences from MemoryStore <a class="header-anchor" href="#differences-from-memorystore" aria-label="Permalink to &quot;Differences from MemoryStore&quot;">​</a></h2><ul><li><strong>Opaque values are JSON.</strong> A run&#39;s <code>output</code>, step <code>input</code>/<code>output</code>/<code>error</code>, checkpoint messages, effect results and state lose <code>Date</code>, <code>undefined</code> and <code>Map</code> fidelity, and a typed array such as <code>Uint8Array</code> comes back as an object keyed by index. A <code>BigInt</code> or a circular structure makes the write throw a <code>TypeError</code>.</li><li><strong>NUL characters and lone surrogates become U+FFFD</strong> in opaque values, keys and strings alike, because <code>jsonb</code> cannot hold them.</li><li><strong>Artifact bytes are <code>bytea</code></strong>, never selected by <code>getArtifact</code> or <code>listArtifacts</code>, and come back from <code>readArtifact</code> as a plain <code>Uint8Array</code>. Postgres caps a <code>bytea</code> value at 1 GB and the whole value travels in one query, so keep artifacts small enough for memory. Nothing purges artifacts yet.</li><li><strong>Identifiers have length limits</strong> (<code>MemoryStore</code> has none): run and artifact ids 128 characters; <code>concurrencyKey</code>, <code>address</code>, claim owners, step names, document collections and document ids 255; idempotency, lock, effect and state keys 512; idempotency scopes 1024 (<code>&lt;agent&gt;:&lt;source&gt;:&lt;kind&gt;:&lt;id&gt;</code> with the invoker URI-encoded, leaving about 950 characters for the encoded <code>kind</code> and <code>id</code>). A longer value makes the write fail with the driver&#39;s <code>value too long</code> error, so validate user-supplied keys before they reach <code>dispatch</code> (a rejected run with an <code>idempotencyKey</code> keeps its key reserved until the key expires).</li><li><strong><code>null</code> in an optional property reads back as absent:</strong> a run <code>output</code> of <code>null</code>, and a step <code>input</code>, <code>output</code> or <code>error</code> of <code>null</code>, are stored as SQL <code>NULL</code>. <code>putEffect(key, undefined)</code> reads back <code>{ result: null }</code> and <code>docUpsert(..., undefined)</code> reads back <code>doc: null</code>.</li><li><strong><code>docList</code> <code>where</code> uses <code>jsonb</code> containment (<code>@&gt;</code>).</strong> Primitive values match by top-level equality; a nested object or array matches by containment, where <code>MemoryStore</code> never matches. A key whose value is <code>undefined</code> matches documents that lack the key, as in <code>MemoryStore</code>. Documents come back ordered by <code>id</code>, not by insertion.</li><li><strong><code>listRuns</code> ties</strong> on <code>createdAt</code> are broken by the byte order of <code>id</code> (<code>COLLATE &quot;C&quot;</code>, so <code>&#39;B&#39; &lt; &#39;a&#39;</code>, reversed for <code>order: &#39;desc&#39;</code>); identical to <code>MemoryStore</code> for lowercase ids and UUIDs.</li></ul>`,23)])])}const y=o(c,[["render",n]]);export{u as __pageData,y as default};
